import{_ as r,C as a,c as n,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Pipeline analysis","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/reporting/pipeline-analysis.md","filePath":"master/sales/crm/reporting/pipeline-analysis.md","lastUpdated":1793789158000}'),l={name:"master/sales/crm/reporting/pipeline-analysis.md"};function g(h,e,p,d,u,c){const o=a("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="pipeline-analysis" tabindex="-1">Pipeline analysis <a class="header-anchor" href="#pipeline-analysis" aria-label="Permalink to &quot;Pipeline analysis&quot;">​</a></h1><p>Pipeline analysis lets you slice your opportunities by any field and add up one number for each slice. You use it to see how much money sits in each stage, which salesperson carries the most deals, and how long deals take to be assigned and closed.</p><blockquote><p><strong>In simple words:</strong> Pick how to group your opportunities, pick what to add up, and read the result as a list or a chart.</p></blockquote><p>Open <code>CRM → Reporting → Pipeline</code>. The page title is <strong>Pipeline Analysis</strong>.</p><h2 id="the-report-page" tabindex="-1">The report page <a class="header-anchor" href="#the-report-page" aria-label="Permalink to &quot;The report page&quot;">​</a></h2>',5)),s(o,{src:"/images1/crm/pipeline-analysis-list.png",alt:"Pipeline analysis list with tabs, Group by, Measure and the summary row"}),e[1]||(e[1]=t('<p>The page has two views: <strong>List</strong> and <strong>Graph</strong>. Use the view switch to change between them.</p><h3 id="views-tabs" tabindex="-1">Views (tabs) <a class="header-anchor" href="#views-tabs" aria-label="Permalink to &quot;Views (tabs)&quot;">​</a></h3><ul><li><strong><em>Default:</em></strong> All opportunities that match the filters.</li><li><strong><em>My Pipeline:</em></strong> Opportunities where you are the salesperson.</li><li><strong><em>Open:</em></strong> Opportunities that are not in a won stage.</li><li><strong><em>Won:</em></strong> Opportunities in a won stage.</li><li><strong><em>Lost:</em></strong> Opportunities you marked as lost.</li></ul><p>Open the tab menu for <strong>Unassigned</strong>, the opportunities with no salesperson.</p><h3 id="default-filter" tabindex="-1">Default filter <a class="header-anchor" href="#default-filter" aria-label="Permalink to &quot;Default filter&quot;">​</a></h3><p>The report starts with the rule <strong>Active</strong>. It hides lost opportunities from the default list. Remove the rule to include them. Use the <strong>Lost</strong> tab to see only lost deals.</p><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><p><strong>Name</strong>, <strong>Type</strong>, <strong>Customer</strong>, <strong>Stage</strong>, <strong>Expected Revenue</strong>, <strong>Probability</strong>, <strong>Salesperson</strong>, <strong>Sales Team</strong>, <strong>Expected Closing</strong>, <strong>Created On</strong> and <strong>Closed On</strong>. Use the column toggle to add <strong>Lost Reason</strong>, <strong>Country</strong> and <strong>City</strong>. The last column shows the measure you chose. A summary row adds it up.</p><h3 id="search-filter-group-and-export" tabindex="-1">Search, filter, group and export <a class="header-anchor" href="#search-filter-group-and-export" aria-label="Permalink to &quot;Search, filter, group and export&quot;">​</a></h3><ul><li>Type in the search box to find an opportunity.</li><li>Use the <strong>Salespeople</strong> and <strong>Sales Teams</strong> filters.</li><li>Use the filter builder for rules on <strong>Salesperson</strong>, <strong>Active</strong>, <strong>Won</strong>, <strong>Closed Date</strong> and other fields.</li><li>Click a row to open the opportunity.</li><li>Select rows, then export them or run a bulk action such as mark as lost, merge, or send email or SMS.</li></ul><h2 id="group-by" tabindex="-1">Group by <a class="header-anchor" href="#group-by" aria-label="Permalink to &quot;Group by&quot;">​</a></h2><p><strong>Group by</strong> folds the rows into groups. Each group shows a subtotal of the measure. The options are:</p><ul><li><strong>Salesperson</strong>, <strong>Sales Team</strong>, <strong>Stage</strong></li><li><strong>City</strong>, <strong>Country</strong>, <strong>Company</strong></li><li><strong>Lost Reason</strong></li><li><strong>Campaign</strong>, <strong>Medium</strong>, <strong>Source</strong></li><li><strong>Expected Closing</strong>, <strong>Creation Date</strong>, <strong>Conversion Date</strong>, <strong>Closed Date</strong> (grouped by month)</li></ul><p>The graph groups by <strong>Stage</strong> at first.</p><h2 id="measure" tabindex="-1">Measure <a class="header-anchor" href="#measure" aria-label="Permalink to &quot;Measure&quot;">​</a></h2><p>Use <strong>Measure</strong> to choose the number the report adds up. The measure is shown as an extra column in the list and as the bar height in the graph.</p><table tabindex="0"><thead><tr><th>Measure</th><th>True meaning</th></tr></thead><tbody><tr><td><strong>Count</strong></td><td>How many opportunities are in the group.</td></tr><tr><td><strong>Expected Revenue</strong></td><td>The sum of <strong>Expected Revenue</strong>. This is the default.</td></tr><tr><td><strong>Prorated Revenue</strong></td><td>The sum of expected revenue times probability divided by 100.</td></tr><tr><td><strong>Probability (avg.)</strong></td><td>The average <strong>Probability</strong> of the group, shown as a percentage.</td></tr><tr><td><strong>Days to Assign</strong></td><td>The average days between creation and the date a salesperson was assigned.</td></tr><tr><td><strong>Days to Close</strong></td><td>The average days between creation and the closed date.</td></tr></tbody></table><h2 id="the-graph-view" tabindex="-1">The Graph view <a class="header-anchor" href="#the-graph-view" aria-label="Permalink to &quot;The Graph view&quot;">​</a></h2>',18)),s(o,{src:"/images1/crm/pipeline-analysis-graph.png",alt:"Pipeline analysis graph showing Expected Revenue by Stage, with Measure and Split by selectors"}),e[2]||(e[2]=t('<ol><li>Click <strong>Graph</strong> in the view switch.</li><li>Choose a <strong>Measure</strong>, for example <strong>Expected Revenue</strong>.</li><li>Choose <strong>Group by</strong> to set the bars. The title shows both, for example <strong>Expected Revenue by Stage</strong>.</li><li>Choose <strong>Split by</strong> to cut each bar by a second field. The default split is <strong>Expected Closing</strong>. Choose <strong>No split</strong> for plain bars.</li></ol><h2 id="read-the-report" tabindex="-1">Read the report <a class="header-anchor" href="#read-the-report" aria-label="Permalink to &quot;Read the report&quot;">​</a></h2><p><strong>Example:</strong> In the list, the <strong>Active</strong> rule leaves four opportunities with a summary of <strong>$2,614,000.00</strong> expected revenue.</p><ol><li>Set <strong>Group by</strong> to <strong>Stage</strong>.</li><li><strong>Proposition</strong> holds two deals: $96,000 and $48,000. Its <strong>Expected Revenue</strong> subtotal is $144,000.</li><li>Change <strong>Measure</strong> to <strong>Prorated Revenue</strong>. <strong>Proposition</strong> drops to $93,600, because the deals are at 70% and 55%.</li><li>Change <strong>Measure</strong> to <strong>Probability (avg.)</strong>. <strong>Proposition</strong> shows 62.5%.</li></ol><p>The first two stages tell you how large the pipeline is. The last tells you how sure you are of it.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To find slow handling, group by <strong>Salesperson</strong> and use <strong>Days to Assign</strong>. A high number means leads wait before someone takes them.</p></div><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><ul><li>The report reads opportunities only. A lead appears here after you convert it.</li><li><strong>Days to Close</strong> counts only opportunities that have a closed date. <strong>Days to Assign</strong> counts only those that were assigned.</li><li>Lost opportunities stay in the data. They show with the stage label <strong>Lost</strong>.</li><li>Nothing you change on this page edits a record.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./forecast.html">Forecast</a></li><li><a href="./lead-analysis.html">Lead analysis</a></li><li><a href="./../pipeline/manage-opportunities.html">Manage opportunities</a></li><li><a href="./">Reporting overview</a></li></ul>',10))])}const y=r(l,[["render",g]]);export{b as __pageData,y as default};
